ValidationRule.errorConditionFormula:
AND( NOT( $Setup.PMC_ProcessSwitches__c.PMC_BypassValidationRule__c ) , NOT( ISCHANGED( PMC_CLM_RebateProgramOrder__c ) ),
OR( AND( NOT( OR( AND( ISCHANGED( Status ) , ISPICKVAL( Status , 'Active') , ISPICKVAL( PMC_SS_SalesAgreement__r.Status , 'Activated')
), AND( ISCHANGED( Status ) , ISPICKVAL( Status , 'Inactive') , ISPICKVAL( PMC_SS_SalesAgreement__r.Status , 'Expired')
) ) ), NOT(ISPICKVAL( PMC_SS_SalesAgreement__r.Status , 'Cancelled')), OR( ISPICKVAL( PMC_SS_SalesAgreement__r.PMC_SS_ApprovalStatus__c , 'Approved'), ISPICKVAL(PMC_SS_SalesAgreement__r.PMC_SS_ApprovalStatus__c, 'Under Revision') ) ), AND( ISNEW(), OR( ISPICKVAL( PMC_SS_SalesAgreement__r.Status , 'Archived'), ISPICKVAL( PMC_SS_SalesAgreement__r.Status , 'Expired'), ISPICKVAL( PMC_SS_SalesAgreement__r.Status , 'Cancelled') ) ) ),
OR((PRIORVALUE( PMC_SS_Projected_Incentive__c ) = PMC_SS_Projected_Incentive__c) ,ISBLANK(PMC_SS_Projected_Incentive__c))
)
